/* Feste Übersetzung der Lerninhalte (fa), maschinell erstellt, nicht von Muttersprachlern geprüft. Code bleibt unverändert. */
(function(r){"use strict";const f=r.SDAkademieFest=r.SDAkademieFest||{};(f["fa"]=f["fa"]||{})["deutsch-beruf"]={"Arbeitsaufträge präzise klären":"دقیق روشن کردن کارهای سپرده‌شده","Du klärst Umfang, Zuständigkeit und Frist eines Arbeitsauftrags, bevor du beginnst.":"پیش از شروع، اندازه، مسئولیت و مهلت یک کار سپرده‌شده را روشن می‌کنی.","Jeweils und insgesamt verwechseln":"اشتباه گرفتن jeweils و insgesamt","Falsch: „Jeweils drei von zwei Dokumenten ergeben drei Blätter.“ Richtig: Es werden insgesamt sechs Ausdrucke benötigt.":"غلط: „Jeweils drei von zwei Dokumenten ergeben drei Blätter.“ درست: در مجموع شش چاپ لازم است.","Modalverb in der Rückfrage vorziehen":"پیش آوردن فعل کمکی در سؤال","Falsch: „Stimmt es, dass ich soll beide Dokumente drucken?“ Richtig: „Stimmt es, dass ich beide Dokumente drucken soll?“":"غلط: „Stimmt es, dass ich soll beide Dokumente drucken?“ درست: „Stimmt es, dass ich beide Dokumente drucken soll?“","Wie viele Ausdrucke benötigt Cem insgesamt?":"Cem در مجموع چند چاپ لازم دارد؟","Drei.":"سه.","Sechs.":"شش.","Zwei.":"دو.","Zwei Dokumente werden jeweils dreimal ausgedruckt, also sechs Exemplare.":"از هر کدام از دو سند سه چاپ گرفته می‌شود، پس شش نسخه.","Welche Frage klärt die Frist?":"کدام سؤال مهلت را روشن می‌کند؟","„Bis wann“ erfragt den Zeitpunkt, zu dem das Ergebnis fertig sein muss.":"„Bis wann“ (تا چه وقت) وقتی را می‌پرسد که نتیجه باید تا آن آماده باشد.","Welche indirekte Frage ist korrekt?":"کدام سؤال غیرمستقیم درست است؟","Im indirekten Fragesatz steht „brauchen“ hinter den Ergänzungen.":"در جملهٔ سؤالی غیرمستقیم „brauchen“ بعد از دیگر اجزای جمله می‌آید.","Wiederhole einen Auftrag in eigenen Worten und stelle eine konkrete Rückfrage zu einer noch fehlenden Angabe.":"یک کار سپرده‌شده را به کلمات خودت تکرار کن و دربارهٔ یک معلوماتِ هنوز کم یک سؤال مشخص بپرس.","Einen unvollständigen Auftrag besprechen":"گفت‌وگو دربارهٔ یک کار ناقص سپرده‌شده","Leiterin: „Bitte bereiten Sie die Unterlagen für den Kundentermin vor.“ Cem: „Meinen Sie das Angebot und die Übersicht der Lieferzeiten?“ Leiterin: „Genau, jeweils drei Ausdrucke.“ Cem: „Bis wann brauchen Sie die Unterlagen?“ Leiterin: „Heute um 13 Uhr.“ Cem: „Dann lege ich die sechs Ausdrucke bis 13 Uhr in den Besprechungsraum.“ Er ergänzt keine weiteren Dokumente nach eigener Vermutung.":"مدیر: „Bitte bereiten Sie die Unterlagen für den Kundentermin vor.“ Cem: „Meinen Sie das Angebot und die Übersicht der Lieferzeiten?“ مدیر: „Genau, jeweils drei Ausdrucke.“ Cem: „Bis wann brauchen Sie die Unterlagen?“ مدیر: „Heute um 13 Uhr.“ Cem: „Dann lege ich die sechs Ausdrucke bis 13 Uhr in den Besprechungsraum.“ او بر اساس حدس خودش هیچ سند دیگری اضافه نمی‌کند.","Rückfragen als indirekte Fragen formulieren":"نوشتن سؤال‌ها به شکل سؤال غیرمستقیم","Mit „Könnten Sie mir sagen, bis wann Sie die Unterlagen brauchen?“ fragst du höflich nach der Frist. Das Fragewort bleibt erhalten, aber das gebeugte Verb schließt den Nebensatz ab. „Habe ich richtig verstanden, dass ich beide Dokumente drucken soll?“ prüft das Verständnis. In der Verbgruppe „drucken soll“ steht das konjugierte Modalverb zuletzt. Sprich die direkte und die indirekte Frage nacheinander.":"با „Könnten Sie mir sagen, bis wann Sie die Unterlagen brauchen?“ مؤدبانه دربارهٔ مهلت می‌پرسی. کلمهٔ سؤالی می‌ماند، اما فعل صرف‌شده جملهٔ فرعی را ختم می‌کند. „Habe ich richtig verstanden, dass ich beide Dokumente drucken soll?“ فهمیدن را بررسی می‌کند. در گروه فعلی „drucken soll“ فعل کمکی صرف‌شده در آخر می‌آید. سؤال مستقیم و غیرمستقیم را پشت سر هم بگو.","Umfang und Ergebnis unterscheiden":"فرق اندازه و نتیجه","Zum Auftrag gehören der Ausdruck – die Ausdrucke, die Frist – die Fristen und die Übersicht – die Übersichten. „Jeweils drei“ bedeutet hier drei Angebote und drei Übersichten. „Insgesamt drei“ wäre eine andere Menge. Eine Aufgabe wie „Unterlagen vorbereiten“ ist weniger genau als ein überprüfbares Ergebnis mit Anzahl, Ort und Zeitpunkt. Notiere diese Angaben in einer kurzen Arbeitsnotiz.":"این کلمه‌ها به کار سپرده‌شده تعلق دارند: der Ausdruck – die Ausdrucke (چاپ)، die Frist – die Fristen (مهلت) و die Übersicht – die Übersichten (جدول خلاصه). „Jeweils drei“ (هر کدام سه) اینجا یعنی سه پیشنهاد قیمت و سه جدول خلاصه. „Insgesamt drei“ (در مجموع سه) یک مقدار دیگر می‌بود. وظیفه‌ای مثل „Unterlagen vorbereiten“ (اسناد را آماده کردن) کمتر از یک نتیجهٔ قابل بررسی با تعداد، جای و وقت دقیق است. این معلومات را در یک یادداشت کاری کوتاه بنویس.","Verständnis sichtbar absichern":"نشان دادن و مطمئن ساختن فهم","Eine Bestätigung wie „Alles klar“ zeigt noch nicht, ob der Auftrag richtig angekommen ist. Wiederhole das Ergebnis: zwei Dokumente, je drei Exemplare, bis 13 Uhr im Besprechungsraum. Wird später ein Dokument geändert, klärst du, welche Version gilt. Falls der Drucker ausfällt, melde die Auswirkung frühzeitig und schlage eine Alternative vor, statt einen nicht erreichbaren Termin stillschweigend zu bestätigen.":"یک تأیید مثل „Alles klar“ (همه روشن است) هنوز نشان نمی‌دهد که کار درست فهمیده شده است. نتیجه را تکرار کن: دو سند، هر کدام سه نسخه، تا ساعت 13 در اتاق جلسه. اگر بعداً یک سند تغییر کند، روشن کن کدام نسخه معتبر است. اگر پرینتر خراب شد، اثر آن را زود خبر بده و یک بدیل پیشنهاد کن، نه اینکه یک وقتِ ناممکن را خاموشانه تأیید کنی.","Eine Rückfrage abschließen":"تمام کردن یک سؤال","Setze „brauchen“ und „soll“ ein.":"„brauchen“ و „soll“ را بگذار.","Die gebeugten Verben schließen die Nebensätze ab.":"فعل‌های صرف‌شده جمله‌های فرعی را ختم می‌کنند.","„Brauchen“ und „soll“ stehen jeweils nach den anderen Satzteilen.":"„Brauchen“ و „soll“ هر کدام بعد از دیگر اجزای جمله می‌آیند.","Auftragsdetails sortieren":"مرتب کردن جزئیات کار سپرده‌شده","Verbinde die Angabe mit ihrer Funktion.":"هر معلومات را به کارکرد آن وصل کن.","Prüfe, welche Frage jede Angabe beantwortet.":"بررسی کن که هر معلومات به کدام سؤال جواب می‌دهد.","Anzahl, Termin und Zielort beschreiben verschiedene Seiten des Auftrags.":"تعداد، وقت و جای مقصد جنبه‌های مختلف کار را بیان می‌کنند.","je drei Ausdrucke":"هر کدام سه چاپ","bis 13 Uhr":"تا ساعت 13","Besprechungsraum":"اتاق جلسه","Die Menge im Auftrag erfassen":"فهمیدن مقدار در کار سپرده‌شده","Wie viele Exemplare soll Cem von jedem Dokument drucken? Schreibe eine Ziffer.":"Cem از هر سند چند نسخه چاپ کند؟ یک عدد بنویس.","Gefragt ist die Anzahl pro Dokument.":"تعداد برای هر سند خواسته شده است.","Von jedem der zwei Dokumente werden drei Exemplare gebraucht.":"از هر کدام از دو سند سه نسخه لازم است.","Eine Auftragsbestätigung schreiben":"نوشتن تأیید یک کار سپرده‌شده","Bestätige beide Dokumente, ihre Anzahl, die Frist und den Ablageort in zwei bis drei Sätzen.":"هر دو سند، تعداد آن‌ها، مهلت و جای گذاشتن را در دو تا سه جمله تأیید کن.","Schreibe ein überprüfbares Ergebnis statt „Ich mache alles fertig“.":"به جای „Ich mache alles fertig“ (همه را آماده می‌کنم) یک نتیجهٔ قابل بررسی بنویس.","Die Bestätigung ermöglicht der Leiterin, ein Missverständnis sofort zu erkennen.":"این تأیید به مدیر اجازه می‌دهد یک سوءتفاهم را فوراً بشناسد.","Sind beide Dokumente eindeutig benannt?":"آیا هر دو سند روشن نام برده شده‌اند؟","Unterscheidest du drei Exemplare je Dokument von sechs insgesamt?":"آیا سه نسخه برای هر سند را از شش نسخه در مجموع جدا می‌کنی؟","Nennst du die Frist heute um 13 Uhr?":"آیا مهلت امروز ساعت 13 را می‌گویی؟","Ist der Besprechungsraum als Ablageort enthalten?":"آیا اتاق جلسه به عنوان جای گذاشتن آمده است؟","Eine Auftragsbestätigung nennt auch Menge und Fertigstellungstermin.":"تأیید یک کار سپرده‌شده مقدار و وقت تمام شدن را هم می‌گوید.","„Jeweils“ bezieht die Anzahl auf jede genannte Gruppe.":"„Jeweils“ تعداد را به هر گروه گفته‌شده مربوط می‌کند.","In Besprechungen berichten und nachfragen":"در جلسه‌ها گزارش دادن و سؤال کردن","Du gibst einen kurzen Arbeitsstand wieder und trennst Ergebnis, Hindernis und nächsten Schritt.":"وضعیت کار را کوتاه می‌گویی و نتیجه، مانع و قدم بعدی را از هم جدا می‌کنی.","Sobald ohne Nebensatzstellung verwenden":"به کار بردن sobald بدون ترتیب جملهٔ فرعی","Falsch: „Sobald die Antwort ist da, ergänze ich die Liste.“ Richtig: „Sobald die Antwort da ist, ergänze ich die Liste.“":"غلط: „Sobald die Antwort ist da, ergänze ich die Liste.“ درست: „Sobald die Antwort da ist, ergänze ich die Liste.“","Entwurf mit bestätigtem Endstand gleichsetzen":"یکی دانستن پیش‌نویس با وضعیت نهاییِ تأییدشده","Falsch: „Alle Termine sind bestätigt“, obwohl zwei fehlen. Richtig: „Der Entwurf enthält zwei ausdrücklich markierte offene Termine.“":"غلط: „Alle Termine sind bestätigt“، در حالی که دو تا کم است. درست: „Der Entwurf enthält zwei ausdrücklich markierte offene Termine.“","Was verhindert den vollständigen Endstand?":"چه چیزی مانع وضعیت نهایی و کامل است؟","Rita hat noch keine Liste begonnen.":"Rita هنوز هیچ فهرستی شروع نکرده است.","Jonas möchte keine Änderungen sehen.":"Jonas نمی‌خواهد هیچ تغییری ببیند.","Die Rückmeldung zu zwei Lieferterminen fehlt.":"جواب دربارهٔ دو وقت تحویل نیامده است.","Rita wartet auf zwei Angaben aus dem Lager; die übrige Liste ist aktualisiert.":"Rita منتظر دو معلومات از گدام است؛ باقی فهرست تازه شده است.","Welcher Satz mit sobald ist korrekt?":"کدام جمله با sobald درست است؟","Das Verb steht im sobald-Satz am Ende und danach vorn im Hauptsatz.":"فعل در جملهٔ sobald در آخر است و بعد از آن در اول جملهٔ اصلی.","Welche Statusmeldung ist am genauesten?":"کدام گزارش وضعیت از همه دقیق‌تر است؟","Alles ist irgendwie fast fertig.":"همه چیز به نوعی تقریباً آماده است.","Die Liste ist aktualisiert; zwei Liefertermine sind noch offen.":"فهرست تازه شده است؛ دو وقت تحویل هنوز باز است.","Es gibt überhaupt keinen Fortschritt.":"اصلاً هیچ پیشرفتی نیست.","Die Meldung benennt sowohl den erreichten Stand als auch die konkrete Lücke.":"این گزارش هم وضعیتِ رسیده‌شده و هم کمبود مشخص را نام می‌برد.","Bereite für eine Besprechung je einen Satz zu Erledigtem, einem Hindernis und der nächsten Handlung vor.":"برای یک جلسه هر کدام یک جمله دربارهٔ کار انجام‌شده، یک مانع و کار بعدی آماده کن.","Einen Arbeitsstand knapp vorstellen":"کوتاه معرفی کردن وضعیت کار","Rita: „Die Liste ist aktualisiert. Zwei Liefertermine fehlen noch, weil ich auf die Rückmeldung des Lagers warte.“ Jonas: „Kannst du trotzdem schon einen Entwurf schicken?“ Rita: „Ja, ich kennzeichne die offenen Termine. Sobald die Antwort da ist, ergänze ich sie.“ Jonas: „Gut, dann besprechen wir morgen nur die Änderungen.“ Rita meldet eine Lücke, ohne den ganzen Auftrag als gescheitert darzustellen.":"Rita: „Die Liste ist aktualisiert. Zwei Liefertermine fehlen noch, weil ich auf die Rückmeldung des Lagers warte.“ Jonas: „Kannst du trotzdem schon einen Entwurf schicken?“ Rita: „Ja, ich kennzeichne die offenen Termine. Sobald die Antwort da ist, ergänze ich sie.“ Jonas: „Gut, dann besprechen wir morgen nur die Änderungen.“ Rita یک کمبود را خبر می‌دهد، بدون اینکه تمام کار را ناکام نشان بدهد.","Zeitliche Grenzen mit sobald ausdrücken":"بیان حدهای زمانی با sobald","„Sobald die Antwort da ist, ergänze ich die Termine“ verknüpft die Ergänzung mit dem Eintreffen der Antwort. „Sobald“ leitet einen Nebensatz mit Endstellung des Verbs ein. Der anschließende Hauptsatz beginnt mit „ergänze“. „Obwohl zwei Angaben fehlen, kann ich einen Entwurf schicken“ betont dagegen einen Gegensatz. Wähle die Verbindung nach der Aussageabsicht, nicht allein danach, welches Wort länger klingt.":"„Sobald die Antwort da ist, ergänze ich die Termine“ تکمیل کردن را به رسیدن جواب وصل می‌کند. „Sobald“ (به محض اینکه) یک جملهٔ فرعی با فعل در آخر را شروع می‌کند. جملهٔ اصلیِ بعد از آن با „ergänze“ شروع می‌شود. „Obwohl zwei Angaben fehlen, kann ich einen Entwurf schicken“ برعکس روی یک تضاد تأکید می‌کند. وصل‌کننده را بر اساس منظور گفته‌ات انتخاب کن، نه فقط بر اساس اینکه کدام کلمه طولانی‌تر به نظر می‌رسد.","Besprechungsbegriffe sicher benutzen":"مطمئن به کار بردن اصطلاحات جلسه","Wichtige Nomen sind der Entwurf – die Entwürfe, die Rückmeldung – die Rückmeldungen und die Änderung – die Änderungen. „Offen“ bedeutet in diesem Zusammenhang noch nicht geklärt. „Aktualisiert“ heißt auf einen neueren Stand gebracht, aber nicht automatisch vollständig geprüft. Sage deshalb genau, welche Teile fertig und welche noch unbestätigt sind. Eine ungeprüfte Lieferzeit bekommt keine erfundene Zusage.":"اسم‌های مهم این‌ها هستند: der Entwurf – die Entwürfe (پیش‌نویس)، die Rückmeldung – die Rückmeldungen (جواب) و die Änderung – die Änderungen (تغییر). „Offen“ (باز) در این زمینه یعنی هنوز روشن نشده. „Aktualisiert“ (تازه‌شده) یعنی به یک وضعیت جدیدتر رسانده شده، اما نه خودبه‌خود کاملاً بررسی‌شده. پس دقیق بگو کدام قسمت‌ها آماده و کدام‌ها هنوز تأیید نشده‌اند. یک وقت تحویلِ بررسی‌نشده نباید یک قول ساختگی بگیرد.","Eine Entscheidung und einen Auftrag festhalten":"یادداشت کردن یک تصمیم و یک کار سپرده‌شده","Notiere nach dem Gespräch: Rita schickt einen Entwurf mit markierten Lücken und ergänzt die Liefertermine nach der Antwort des Lagers. Die nächste Besprechung behandelt Änderungen. Wenn du eine Aussage nicht verstanden hast, frage „Meinst du mit Entwurf die Liste ohne die beiden Termine?“. Eine solche Rückfrage konkretisiert den Inhalt. Wiederhole anschließend die vereinbarte Handlung, damit alle denselben Stand haben.":"بعد از گفت‌وگو یادداشت کن: Rita یک پیش‌نویس با کمبودهای نشانی‌شده می‌فرستد و وقت‌های تحویل را بعد از جواب گدام تکمیل می‌کند. جلسهٔ بعدی دربارهٔ تغییرها است. اگر یک گفته را نفهمیدی، بپرس „Meinst du mit Entwurf die Liste ohne die beiden Termine?“. چنین سؤالی محتوا را مشخص‌تر می‌سازد. بعد کارِ توافق‌شده را تکرار کن تا همه یک وضعیت را بدانند.","Den nächsten Schritt verknüpfen":"وصل کردن قدم بعدی","Setze „Sobald“ und „ergänze“ ein.":"„Sobald“ و „ergänze“ را بگذار.","Ein Wort leitet die zeitliche Bedingung ein, das andere beginnt den Hauptsatz.":"یک کلمه شرط زمانی را شروع می‌کند، کلمهٔ دیگر جملهٔ اصلی را.","Beide Sätze koppeln die Ergänzung an die Antwort des Lagers.":"هر دو جمله تکمیل کردن را به جواب گدام وابسته می‌سازند.","Statuswörter zuordnen":"وصل کردن کلمه‌های وضعیت","Verbinde den Begriff mit seiner Bedeutung.":"هر اصطلاح را به معنای آن وصل کن.","Eine vorläufige Fassung kann bereits aktualisiert sein.":"یک نسخهٔ موقت می‌تواند از قبل تازه شده باشد.","Die Begriffe unterscheiden Reifegrad, Lücken und Aktualität.":"این اصطلاحات درجهٔ آمادگی، کمبودها و تازه بودن را از هم جدا می‌کنند.","Entwurf":"پیش‌نویس","offen":"باز، هنوز روشن نشده","aktualisiert":"تازه‌شده","Offene Angaben zählen":"شمردن معلومات باز","Wie viele Liefertermine fehlen noch? Schreibe eine Ziffer.":"چند وقت تحویل هنوز کم است؟ یک عدد بنویس.","Zähle die fehlenden, nicht die bestätigten Termine.":"وقت‌های کم را بشمار، نه وقت‌های تأییدشده را.","Zwei Felder sind noch offen und werden später ergänzt.":"دو خانه هنوز باز است و بعداً تکمیل می‌شود.","Eine kurze Besprechungsnotiz verfassen":"نوشتن یک یادداشت کوتاه جلسه","Notiere Ritas Stand, die offene Information und die vereinbarten nächsten Schritte in drei Sätzen.":"وضعیت Rita، معلومات باز و قدم‌های بعدیِ توافق‌شده را در سه جمله یادداشت کن.","Vermeide „fertig“, solange die zwei Liefertermine fehlen.":"تا وقتی دو وقت تحویل کم است، „fertig“ (آماده) نگو.","Die Notiz enthält Stand, Abhängigkeit und vereinbarte Weiterarbeit.":"این یادداشت وضعیت، وابستگی و ادامهٔ کارِ توافق‌شده را دارد.","Sind aktualisierte und offene Teile getrennt beschrieben?":"آیا قسمت‌های تازه‌شده و باز جدا توضیح داده شده‌اند؟","Nennst du das Lager als Quelle der fehlenden Angaben?":"آیا گدام را منبع معلومات کم می‌گویی؟","Steht die Markierung der Lücken in deiner Notiz?":"آیا نشانی کردن کمبودها در یادداشتت آمده است؟","Hat der sobald-Satz die korrekte Verbposition?":"آیا جملهٔ sobald جای درست فعل را دارد؟","Ein Arbeitsstand darf eine klar bezeichnete Lücke enthalten.":"وضعیت کار می‌تواند یک کمبودِ روشن نام‌برده‌شده داشته باشد.","„Sobald“ benennt den frühesten Auslöser für den nächsten Schritt.":"„Sobald“ زودترین محرک برای قدم بعدی را نام می‌برد.","Berufliche E-Mails mit klarer Bitte":"ایمیل‌های کاری با خواهش روشن","Du formulierst Betreff, Kontext und gewünschte Rückmeldung passend zu einer beruflichen Nachricht.":"موضوع، زمینه و جواب خواسته‌شده را مناسب با یک پیام کاری می‌نویسی.","Zu beim trennbaren Verb falsch setzen":"گذاشتن غلط zu در فعل جداشدنی","Falsch: „um das Angebot zu fertigstellen“. Richtig: „um das Angebot fertigzustellen“. „Zu“ steht zwischen „fertig“ und „stellen“.":"غلط: „um das Angebot zu fertigstellen“. درست: „um das Angebot fertigzustellen“. „Zu“ بین „fertig“ و „stellen“ می‌آید.","Benötigten Termin als Zusage ausgeben":"وقتِ مورد نیاز را مثل یک قول نشان دادن","Falsch: „Sie haben morgen zehn Uhr zugesagt“, obwohl nur der eigene Bedarf genannt wurde. Richtig: „Ich benötige die Preise bis morgen um zehn Uhr.“":"غلط: „Sie haben morgen zehn Uhr zugesagt“، در حالی که فقط نیاز خودت گفته شده بود. درست: „Ich benötige die Preise bis morgen um zehn Uhr.“","Welcher Betreff passt am besten zur Nachricht?":"کدام موضوع ایمیل با پیام بیشتر مناسب است؟","Der Betreff nennt das Dokument und die gewünschte Reaktion knapp.":"موضوع ایمیل سند و واکنش خواسته‌شده را کوتاه می‌گوید.","Welche Infinitivgruppe ist richtig?":"کدام گروه مصدری درست است؟","Beim trennbaren Verb wird „zu“ zwischen Vorsilbe und Verbstamm eingefügt.":"در فعل جداشدنی، „zu“ بین پیشوند و ریشهٔ فعل می‌آید.","Was benötigt Dalia bis morgen um zehn?":"Dalia تا فردا ساعت ده به چه چیزی نیاز دارد؟","Eine neue Computermaus.":"یک موس تازهٔ کمپیوتر.","Die Preise für das Angebot.":"قیمت‌ها برای پیشنهاد قیمت.","Die fertige Rechnung des Kunden.":"بل آمادهٔ مشتری.","Dalia nennt die Preise als Voraussetzung, um ihr Angebot zu erstellen.":"Dalia قیمت‌ها را شرط ساختن پیشنهاد قیمتش می‌گوید.","Lies nur den Betreff und den letzten Satz: Ist bereits erkennbar, was die empfangende Person tun soll?":"فقط موضوع و جملهٔ آخر را بخوان: آیا از قبل معلوم است که گیرنده چه کاری باید بکند؟","Eine fehlende Datei anfordern":"خواستن یک فایل کم‌بوده","Sven: „Ich habe die Preisliste geschickt.“ Dalia: „Danke, aber der Anhang lässt sich bei mir nicht öffnen.“ Sven: „Soll ich sie noch einmal senden?“ Dalia: „Ja, bitte als PDF. Für das Angebot brauche ich die Preise bis morgen um zehn.“ Sven: „Ich schicke die Datei heute Nachmittag.“ Die Bitte nennt Dateiformat und Zweck. Dalia erklärt eine technische Beobachtung, ohne Sven einen Fehler zu unterstellen.":"Sven: „Ich habe die Preisliste geschickt.“ Dalia: „Danke, aber der Anhang lässt sich bei mir nicht öffnen.“ Sven: „Soll ich sie noch einmal senden?“ Dalia: „Ja, bitte als PDF. Für das Angebot brauche ich die Preise bis morgen um zehn.“ Sven: „Ich schicke die Datei heute Nachmittag.“ این خواهش شکل فایل و هدف را می‌گوید. Dalia یک مشاهدهٔ تخنیکی را توضیح می‌دهد، بدون اینکه Sven را مقصر بداند.","Zweck und Handlung sprachlich verbinden":"وصل کردن زبانی هدف و کار","„Damit ich das Angebot fertigstellen kann, brauche ich die Preisliste“ erklärt den Zweck mit eigenem Subjekt. Bei gleichem Handelnden ist auch „Ich brauche die Liste, um das Angebot fertigzustellen“ möglich. Beim trennbaren Verb „fertigstellen“ steht „zu“ zwischen den Bestandteilen: „fertigzustellen“. „Bitte senden Sie …“ nennt die Handlung direkt. „Ich hätte gern …“ ist höflich, braucht aber ebenfalls eine eindeutige Ergänzung.":"„Damit ich das Angebot fertigstellen kann, brauche ich die Preisliste“ هدف را با یک فاعل جداگانه توضیح می‌دهد. وقتی انجام‌دهنده یکی است، „Ich brauche die Liste, um das Angebot fertigzustellen“ هم ممکن است. در فعل جداشدنی „fertigstellen“ (تمام کردن) کلمهٔ „zu“ بین دو قسمت می‌آید: „fertigzustellen“. „Bitte senden Sie …“ کار را مستقیم می‌گوید. „Ich hätte gern …“ مؤدبانه است، اما آن هم یک تکمیل روشن لازم دارد.","Dateien und Versionen benennen":"نام بردن فایل‌ها و نسخه‌ها","Lerne der Anhang – die Anhänge, das Angebot – die Angebote und die Fassung – die Fassungen. Ein Dateiname wie „Preisliste_November.pdf“ hilft bei der Zuordnung. „Die aktuelle Liste“ kann unklar sein, wenn mehrere Fassungen vorliegen. Nenne deshalb bei Bedarf Datum oder Versionsstand. Bevor du „im Anhang“ schreibst, kontrolliere, ob die Datei wirklich angehängt und für die empfangende Person bestimmt ist.":"یاد بگیر: der Anhang – die Anhänge (ضمیمه)، das Angebot – die Angebote (پیشنهاد قیمت) و die Fassung – die Fassungen (نسخه). نام فایلی مثل „Preisliste_November.pdf“ شناختن را آسان می‌سازد. „Die aktuelle Liste“ (فهرست فعلی) می‌تواند ناروشن باشد، اگر چند نسخه موجود باشد. پس در صورت لزوم تاریخ یا شمارهٔ نسخه را بگو. پیش از اینکه „im Anhang“ (در ضمیمه) بنویسی، بررسی کن که فایل واقعاً ضمیمه شده و برای همان گیرنده است.","Die Nachricht vor dem Versand kürzen":"کوتاه کردن پیام پیش از فرستادن","Beginne mit dem Anlass und stelle danach die Bitte. Ein brauchbarer Betreff lautet „Preisliste erneut als PDF erbeten“. Ein langer Bericht über sämtliche Computerprobleme lenkt davon ab. Nenne den benötigten Zeitpunkt präzise und unterscheide ihn von einem bereits zugesagten Versand. Prüfe Empfänger, Anhang und Zahlen zuletzt. Eine freundliche Schlussformel ersetzt keine fehlende Angabe zum gewünschten Dateiformat.":"با دلیل نامه شروع کن و بعد خواهش را بگو. یک موضوع مناسب این است: „Preisliste erneut als PDF erbeten“. یک گزارش طولانی دربارهٔ همهٔ مشکلات کمپیوتر توجه را از اصل دور می‌کند. وقتِ مورد نیاز را دقیق بگو و آن را از یک فرستادنِ از قبل قول‌داده‌شده جدا کن. در آخر گیرنده، ضمیمه و عددها را بررسی کن. یک جملهٔ پایانی مهربان، معلوماتِ کم دربارهٔ شکل خواسته‌شدهٔ فایل را جبران نمی‌کند.","Zweckangaben vervollständigen":"تکمیل بیان هدف","Ergänze „kann“ und „fertigzustellen“.":"„kann“ و „fertigzustellen“ را تکمیل کن.","Das Modalverb schließt den damit-Satz ab; im zweiten Satz steht eine Infinitivgruppe.":"فعل کمکی جملهٔ damit را ختم می‌کند؛ در جملهٔ دوم یک گروه مصدری می‌آید.","„Kann“ steht hinten, „fertigzustellen“ enthält das eingeschobene „zu“.":"„Kann“ در آخر است، „fertigzustellen“ کلمهٔ „zu“ را در میان دارد.","Nachrichtenteile erkennen":"شناختن قسمت‌های پیام","Ordne den Text der Funktion zu.":"متن را به کارکرد آن وصل کن.","Suche Thema, Problem und gewünschte Reaktion.":"موضوع، مشکل و واکنش خواسته‌شده را پیدا کن.","Die Zuordnung zeigt einen übersichtlichen Aufbau der E-Mail.":"این وصل کردن یک ساختار منظم ایمیل را نشان می‌دهد.","Preisliste als PDF":"فهرست قیمت به شکل PDF","Der Anhang lässt sich nicht öffnen.":"ضمیمه باز نمی‌شود.","Bitte senden Sie die Datei erneut.":"لطفاً فایل را دوباره بفرستید.","Das benötigte Format hören":"شنیدن شکل مورد نیاز فایل","In welchem Dateiformat soll Sven die Liste schicken?":"Sven فهرست را به کدام شکل فایل بفرستد؟","Die letzte Bitte benennt das Dateiformat ausdrücklich.":"خواهش آخر شکل فایل را صریح نام می‌برد.","Dalia benötigt eine PDF-Fassung der Preisliste.":"Dalia یک نسخهٔ PDF فهرست قیمت لازم دارد.","Schreibe eine E-Mail an Sven: Anhang nicht lesbar, PDF erbitten, Preise bis morgen 10 Uhr benötigt.":"یک ایمیل به Sven بنویس: ضمیمه خوانده نمی‌شود، PDF خواسته می‌شود، قیمت‌ها تا فردا ساعت 10 لازم است.","Formuliere den Bedarfstermin als eigene Bitte, nicht als fremde Zusage.":"وقتِ مورد نیاز را به عنوان خواهش خودت بنویس، نه به عنوان قول یک شخص دیگر.","Die Nachricht enthält Anlass, gewünschtes Format, Termin und Zweck.":"این پیام دلیل نامه، شکل خواسته‌شده، وقت و هدف را دارد.","Nennt der Betreff Dokument und Anliegen?":"آیا موضوع ایمیل سند و خواست را نام می‌برد؟","Beschreibst du das Öffnungsproblem ohne persönlichen Vorwurf?":"آیا مشکل باز شدن را بدون ملامتی شخصی توضیح می‌دهی؟","Bittest du ausdrücklich um das PDF-Format?":"آیا صریح شکل PDF را می‌خواهی؟","Sind Bedarfstermin und Zweck der Liste enthalten?":"آیا وقتِ مورد نیاز و هدف فهرست آمده است؟","Eine berufliche Bitte nennt die gewünschte Handlung und ihren Zweck.":"یک خواهش کاری، کار خواسته‌شده و هدف آن را می‌گوید.","Bei „fertigzustellen“ steht „zu“ innerhalb des trennbaren Verbs.":"در „fertigzustellen“ کلمهٔ „zu“ در درون فعل جداشدنی است.","Am Betriebstelefon Nachrichten aufnehmen":"گرفتن پیام در تیلفون شرکت","Du hältst Rückrufdaten fest und bestätigst Namen, Nummer und Anliegen.":"معلومات برای زنگ زدن دوباره را یادداشت می‌کنی و نام، شماره و خواست را تأیید می‌کنی.","Einen unbestätigten Rückruf versprechen":"قول دادن یک زنگ دوبارهٔ تأییدنشده","Falsch: „Frau Wolf ruft garantiert in fünf Minuten an“, ohne Rücksprache. Richtig: „Ich gebe Ihre Bitte um Rückruf weiter.“":"غلط: „Frau Wolf ruft garantiert in fünf Minuten an“، بدون مشوره. درست: „Ich gebe Ihre Bitte um Rückruf weiter.“","Durchwahl ungeprüft verändern":"بدون بررسی تغییر دادن شمارهٔ داخلی","Falsch: Aus „zwei vier sechs“ die Nummer 264 notieren. Richtig: 246 zurücklesen und die Bestätigung abwarten.":"غلط: از „zwei vier sechs“ شمارهٔ 264 را یادداشت کردن. درست: 246 را دوباره خواندن و منتظر تأیید ماندن.","Was darf Kaya ohne weitere Absprache zusagen?":"Kaya بدون مشورهٔ بیشتر چه قولی داده می‌تواند؟","Frau Wolf ruft in fünf Minuten zurück.":"خانم Wolf پنج دقیقه بعد دوباره زنگ می‌زند.","Das Angebot wird heute angenommen.":"پیشنهاد قیمت امروز قبول می‌شود.","Die Rückrufbitte wird weitergegeben.":"خواهش زنگ دوباره رسانده می‌شود.","Kaya kann die eigene Weitergabe zusagen, aber keine fremde Reaktion garantieren.":"Kaya می‌تواند رساندن پیام توسط خودش را قول بدهد، اما واکنش یک شخص دیگر را تضمین کرده نمی‌تواند.","Welche Durchwahl nennt Herr Demir?":"آقای Demir کدام شمارهٔ داخلی را می‌گوید؟","Im Gespräch werden die Ziffern zwei, vier, sechs ausdrücklich bestätigt.":"در گفت‌وگو عددهای دو، چهار، شش صریح تأیید می‌شوند.","Welche Nachricht gibt das Anliegen korrekt wieder?":"کدام پیام خواست را درست بازگو می‌کند؟","Herr Demir bestätigt den Auftrag.":"آقای Demir سفارش را تأیید می‌کند.","Herr Demir bittet Frau Wolf um Rückruf zum Angebot.":"آقای Demir از خانم Wolf می‌خواهد دربارهٔ پیشنهاد قیمت دوباره زنگ بزند.","Frau Wolf soll die Rechnung stornieren.":"خانم Wolf باید بل را لغو کند.","Ein Rückruf zum Angebot ist genannt; Auftrag oder Stornierung werden nicht vereinbart.":"یک زنگ دوباره دربارهٔ پیشنهاد قیمت گفته شده؛ سفارش یا لغو توافق نشده است.","Lies eine notierte Nummer Ziffer für Ziffer zurück und frage bei Unsicherheit sofort nach.":"یک شمارهٔ یادداشت‌شده را عدد به عدد دوباره بخوان و اگر مطمئن نبودی فوراً بپرس.","Einen Rückruf aufnehmen":"گرفتن یک خواهش زنگ دوباره","Zentrale: „Guten Tag, Firma Morgenrot, Kaya am Apparat.“ Anrufer: „Hier spricht Herr Demir. Kann ich Frau Wolf sprechen?“ Kaya: „Sie ist gerade in einer Besprechung. Darf ich ihr etwas ausrichten?“ Demir: „Bitte um Rückruf wegen des Angebots. Meine Durchwahl ist 246.“ Kaya: „Ich notiere: Herr Demir, Rückruf zum Angebot, Durchwahl zwei vier sechs. Ist das richtig?“ Demir: „Ja, vielen Dank.“":"تیلفون مرکزی: „Guten Tag, Firma Morgenrot, Kaya am Apparat.“ زنگ‌زننده: „Hier spricht Herr Demir. Kann ich Frau Wolf sprechen?“ Kaya: „Sie ist gerade in einer Besprechung. Darf ich ihr etwas ausrichten?“ Demir: „Bitte um Rückruf wegen des Angebots. Meine Durchwahl ist 246.“ Kaya: „Ich notiere: Herr Demir, Rückruf zum Angebot, Durchwahl zwei vier sechs. Ist das richtig?“ Demir: „Ja, vielen Dank.“","Auskünfte und Nachrichten unterscheiden":"فرق معلومات دادن و پیام رساندن","„Frau Wolf ist in einer Besprechung“ beschreibt den bekannten Status. „Sie ruft Sie um zwölf zurück“ wäre eine Zusage, die Kaya ohne Absprache nicht machen sollte. Eine sichere Formulierung lautet „Ich richte Ihre Bitte um Rückruf aus“. In der indirekten Wiedergabe passt „Herr Demir bittet darum, dass Frau Wolf ihn zurückruft“. Beim trennbaren Verb steht im Nebensatz „zurückruft“ zusammen am Schluss.":"„Frau Wolf ist in einer Besprechung“ وضعیتِ معلوم را توضیح می‌دهد. „Sie ruft Sie um zwölf zurück“ یک قول می‌بود که Kaya بدون مشوره نباید بدهد. یک عبارت مطمئن این است: „Ich richte Ihre Bitte um Rückruf aus“. در بازگویی غیرمستقیم „Herr Demir bittet darum, dass Frau Wolf ihn zurückruft“ مناسب است. در فعل جداشدنی، در جملهٔ فرعی „zurückruft“ با هم در آخر می‌آید.","Telefonwörter und höfliche Rückfragen":"کلمه‌های تیلفون و سؤال‌های مؤدبانه","Zum Telefonat gehören der Rückruf – die Rückrufe, die Durchwahl – die Durchwahlen und die Nachricht – die Nachrichten. „Darf ich Ihren Namen noch einmal hören?“ ist eine höfliche Rückfrage. Zum Buchstabieren kannst du um einzelne Buchstaben bitten, ohne eine unbekannte Buchstabiertafel zu erfinden. Unterscheide eine interne Durchwahl von einer vollständigen Rufnummer und kläre, welche Angabe für den Rückruf benötigt wird.":"به تیلفون این کلمه‌ها تعلق دارند: der Rückruf – die Rückrufe (زنگ دوباره)، die Durchwahl – die Durchwahlen (شمارهٔ داخلی) و die Nachricht – die Nachrichten (پیام). „Darf ich Ihren Namen noch einmal hören?“ یک سؤال مؤدبانه است. برای هجی کردن می‌توانی حرف‌های جداگانه را بخواهی، بدون اینکه یک جدول هجیِ ناشناخته بسازی. شمارهٔ داخلی را از یک شمارهٔ کامل تیلفون جدا کن و روشن کن کدام معلومات برای زنگ دوباره لازم است.","Die Notiz auf das Nötige begrenzen":"محدود کردن یادداشت به ضروریات","Halte fest, wer angerufen hat, für wen die Nachricht ist und worum es geht. Notiere nur Angaben, die für die Weitergabe im Betrieb erforderlich sind. Wiederhole Zahlen langsam und bestätige sie. Schreibe nicht „dringend“, wenn die anrufende Person das nicht gesagt hat. Kannst du den Namen nicht sicher verstehen, markiere die Unsicherheit und frage nach, statt einen ähnlich klingenden Namen einzusetzen.":"یادداشت کن چه کسی زنگ زد، پیام برای کیست و دربارهٔ چیست. فقط معلوماتی را بنویس که برای رساندن پیام در شرکت لازم است. عددها را آهسته تکرار کن و تأیید کن. „dringend“ (عاجل) ننویس، اگر زنگ‌زننده آن را نگفته است. اگر نام را مطمئن نفهمیدی، نامطمئنی را نشانی کن و بپرس، نه اینکه یک نامِ شبیه بگذاری.","Eine Nachricht weitergeben":"رساندن یک پیام","Setze „zurückruft“ und „ausrichten“ ein.":"„zurückruft“ و „ausrichten“ را بگذار.","Im Nebensatz wird das trennbare Verb zusammengeschrieben.":"در جملهٔ فرعی فعل جداشدنی با هم نوشته می‌شود.","„Zurückruft“ steht als gebeugtes Verb am Ende, „ausrichten“ als Infinitiv nach „darf“.":"„Zurückruft“ به عنوان فعل صرف‌شده در آخر است، „ausrichten“ به عنوان مصدر بعد از „darf“.","Telefonangaben ordnen":"مرتب کردن معلومات تیلفون","Verbinde die Angabe mit ihrer Bedeutung.":"هر معلومات را به معنای آن وصل کن.","Unterscheide Absender, Empfängerin und Rückrufangabe.":"فرستنده، گیرنده و معلومات زنگ دوباره را از هم جدا کن.","Die drei Angaben erfüllen verschiedene Zwecke in der Telefonnotiz.":"این سه معلومات در یادداشت تیلفون هدف‌های مختلف دارند.","Die Durchwahl notieren":"یادداشت کردن شمارهٔ داخلی","Schreibe die Durchwahl als drei Ziffern.":"شمارهٔ داخلی را به شکل سه عدد بنویس.","Notiere die Ziffern in derselben Reihenfolge.":"عددها را به همان ترتیب یادداشت کن.","Die bestätigte Durchwahl lautet 246.":"شمارهٔ داخلیِ تأییدشده 246 است.","Eine Telefonnotiz schreiben":"نوشتن یک یادداشت تیلفون","Notiere Anrufer, Empfängerin, Anliegen und Durchwahl. Erfinde keine Rückrufzeit.":"زنگ‌زننده، گیرنده، خواست و شمارهٔ داخلی را یادداشت کن. هیچ وقتی برای زنگ دوباره از خود نساز.","Lies die Notiz so, als hätte Frau Wolf das Telefonat nicht mitgehört.":"یادداشت را طوری بخوان که گویی خانم Wolf تیلفون را نشنیده است.","Die Empfängerin bekommt alle vereinbarten Angaben ohne zusätzliche Versprechen.":"گیرنده همهٔ معلومات توافق‌شده را بدون قول‌های اضافی می‌گیرد.","Sind Herr Demir und Frau Wolf richtig zugeordnet?":"آیا آقای Demir و خانم Wolf درست جای داده شده‌اند؟","Nennst du das Angebot als Anlass des Rückrufs?":"آیا پیشنهاد قیمت را دلیل زنگ دوباره می‌گویی؟","Ist die Durchwahl 246 ohne Zahlendreher notiert?":"آیا شمارهٔ داخلی 246 بدون جابه‌جایی عددها یادداشت شده است؟","Verzichtest du auf eine unbestätigte Rückrufzusage?":"آیا از قول زنگ دوبارهٔ تأییدنشده دوری می‌کنی؟","Eine Rückrufnotiz hält das Anliegen ohne erfundene Dringlichkeit fest.":"یک یادداشت زنگ دوباره خواست را بدون عاجل بودنِ ساختگی نگه می‌دارد.","Ziffern zurückzulesen macht Zahlendreher erkennbar.":"دوباره خواندن عددها جابه‌جایی عددها را قابل شناخت می‌سازد.","Arbeitsabläufe im Passiv beschreiben":"توضیح جریان کار با Passiv (مجهول)","Du beschreibst einen betrieblichen Ablauf und unterscheidest Tätigkeit und ausführende Person.":"یک جریان کار در شرکت را توضیح می‌دهی و کار را از شخص انجام‌دهنده جدا می‌کنی.","Passiv und Plural nicht abstimmen":"هماهنگ نکردن Passiv و جمع","Falsch: „Die Waren wird geprüft.“ Richtig: „Die Waren werden geprüft.“ Das Subjekt steht im Plural.":"غلط: „Die Waren wird geprüft.“ درست: „Die Waren werden geprüft.“ فاعل جمع است.","Partizip von verschicken falsch bilden":"ساختن غلط Partizip برای verschicken","Falsch: „Das Paket wird geverschickt.“ Richtig: „Das Paket wird verschickt.“ Die Vorsilbe „ver-“ schließt hier „ge-“ aus.":"غلط: „Das Paket wird geverschickt.“ درست: „Das Paket wird verschickt.“ پیشوند „ver-“ اینجا „ge-“ را نمی‌پذیرد.","Welche Passivform passt zu „die Waren“?":"کدام شکل Passiv با „die Waren“ مناسب است؟","Zum Plural gehört „werden“; das Vollverb steht als Partizip „geprüft“.":"با جمع „werden“ می‌آید؛ فعل اصلی به شکل Partizip „geprüft“ است.","Welcher Satz nennt die zuständige Gruppe ausdrücklich?":"کدام جمله گروه مسئول را صریح نام می‌برد؟","Nur diese Aussage bezeichnet mit dem Versandteam die handelnde Gruppe.":"فقط این جمله با تیم ارسال، گروه انجام‌دهنده را نام می‌برد.","Was passiert laut Ablauf zuerst?":"طبق جریان کار، اول چه اتفاق می‌افتد؟","Die Auftragsprüfung steht vor Zusammenstellung, Wiegen und Versand.":"بررسی سفارش پیش از جمع کردن، وزن کردن و فرستادن است.","Unterstreiche in einem Ablauf die Verben und prüfe, ob gerade die Handlung oder die handelnde Person wichtig ist.":"در یک جریان کار زیر فعل‌ها خط بکش و بررسی کن که آیا کار مهم است یا شخص انجام‌دهنده.","Einen Versandablauf erklären":"توضیح دادن جریان ارسال","Milan: „Was passiert mit einer Bestellung?“ Kollegin: „Zuerst wird der Auftrag geprüft. Danach werden die Waren zusammengestellt.“ Milan: „Wer kontrolliert die Adresse?“ Kollegin: „Das macht unser Versandteam. Anschließend wird das Paket gewogen und verschickt.“ Milan: „Dann prüfe ich zuerst den Auftrag und frage bei fehlenden Angaben nach.“ Die Erklärung beschreibt die Reihenfolge; eine wichtige Zuständigkeit wird bei Bedarf ausdrücklich genannt.":"Milan: „Was passiert mit einer Bestellung?“ همکار: „Zuerst wird der Auftrag geprüft. Danach werden die Waren zusammengestellt.“ Milan: „Wer kontrolliert die Adresse?“ همکار: „Das macht unser Versandteam. Anschließend wird das Paket gewogen und verschickt.“ Milan: „Dann prüfe ich zuerst den Auftrag und frage bei fehlenden Angaben nach.“ این توضیح ترتیب را می‌گوید؛ یک مسئولیت مهم در صورت لزوم صریح نام برده می‌شود.","Das Vorgangspassiv mit werden bilden":"ساختن Passiv جریانی با werden","Im Präsens lautet die Form „werden“ plus Partizip II: „Der Auftrag wird geprüft.“ Bei einem Subjekt im Plural heißt es „Die Waren werden geprüft“. Das Subjekt bezeichnet jetzt das, woran etwas geschieht. Im Aktiv heißt es „Das Team prüft den Auftrag“. Eine handelnde Person kann im Passiv mit „von“ ergänzt werden: „Der Auftrag wird vom Team geprüft“. Entscheide nach dem Inhalt, ob diese Ergänzung nötig ist.":"در زمان حال شکل آن „werden“ به اضافهٔ Partizip II است: „Der Auftrag wird geprüft.“ با فاعل جمع می‌شود „Die Waren werden geprüft“. فاعل حالا چیزی را نشان می‌دهد که کاری روی آن انجام می‌شود. در معلوم (Aktiv) می‌شود „Das Team prüft den Auftrag“. یک شخص انجام‌دهنده در Passiv با „von“ اضافه شده می‌تواند: „Der Auftrag wird vom Team geprüft“. بر اساس محتوا تصمیم بگیر که آیا این اضافه لازم است.","Verben und Nomen im Versand":"فعل‌ها و اسم‌ها در ارسال","Du brauchst der Auftrag – die Aufträge, die Ware – die Waren und das Paket – die Pakete. „Zusammenstellen“ ist trennbar; sein Partizip lautet „zusammengestellt“. „Verschicken“ bildet „verschickt“ ohne zusätzliches „ge“. „Wird verschickt“ beschreibt einen Vorgang; „ist verschickt worden“ berichtet über einen abgeschlossenen Vorgang im Perfekt. In dieser Lektion übst du zunächst das Passiv im Präsens mit klarer Reihenfolge.":"این کلمه‌ها را لازم داری: der Auftrag – die Aufträge (سفارش، کار سپرده‌شده)، die Ware – die Waren (جنس) و das Paket – die Pakete (بسته). „Zusammenstellen“ (جمع کردن) جداشدنی است؛ Partizip آن „zusammengestellt“ است. „Verschicken“ (فرستادن) شکل „verschickt“ را بدون „ge“ اضافی می‌سازد. „Wird verschickt“ یک جریان را توضیح می‌دهد؛ „ist verschickt worden“ از یک جریانِ تمام‌شده در Perfekt خبر می‌دهد. در این درس اول Passiv را در زمان حال با یک ترتیب روشن تمرین می‌کنی.","Verantwortung trotz Passiv sichtbar halten":"با وجود Passiv مسئولیت را نمایان نگه داشتن","Das Passiv ist nützlich für Anleitungen, kann aber Zuständigkeiten verdecken. „Die Adresse wird kontrolliert“ sagt noch nicht, wer dafür verantwortlich ist. Ergänze bei einem Arbeitsauftrag das Versandteam oder formuliere aktiv. Prüfe außerdem, ob „wird“ zum Singular und „werden“ zum Plural passt. Erzähle den Ablauf anschließend einmal aus Sicht des Teams im Aktiv und einmal als neutrale Prozessbeschreibung im Passiv.":"Passiv برای رهنمودها مفید است، اما می‌تواند مسئولیت‌ها را پنهان کند. „Die Adresse wird kontrolliert“ هنوز نمی‌گوید چه کسی مسئول است. در یک کار سپرده‌شده تیم ارسال را اضافه کن یا به شکل معلوم بنویس. همچنین بررسی کن که „wird“ با مفرد و „werden“ با جمع مناسب باشد. بعد جریان کار را یک بار از نظر تیم به شکل معلوم و یک بار به عنوان توضیح بی‌طرفِ جریان به شکل Passiv قصه کن.","Passivformen einsetzen":"گذاشتن شکل‌های Passiv","Setze „wird“ und „werden“ ein.":"„wird“ و „werden“ را بگذار.","Bestimme bei jedem Satz die Zahl des Subjekts.":"در هر جمله تعداد فاعل را تعیین کن.","Der einzelne Auftrag verlangt „wird“, mehrere Pakete verlangen „werden“.":"یک سفارش „wird“ می‌خواهد، چند بسته „werden“.","Aktiv und Passiv verbinden":"وصل کردن Aktiv و Passiv","Ordne die gleichbedeutenden Aussagen zu.":"جمله‌های هم‌معنا را به هم وصل کن.","Die Handlung bleibt gleich; die Perspektive ändert sich.":"کار همان می‌ماند؛ زاویهٔ دید تغییر می‌کند.","Im Passiv steht das von der Handlung betroffene Objekt als Subjekt.":"در Passiv چیزی که کار روی آن انجام می‌شود، فاعل است.","Das Team prüft den Auftrag.":"تیم سفارش را بررسی می‌کند.","Das Team wiegt die Pakete.":"تیم بسته‌ها را وزن می‌کند.","Das Team verschickt die Ware.":"تیم جنس را می‌فرستد.","Die zuständige Gruppe verstehen":"فهمیدن گروه مسئول","Wer kontrolliert die Adresse?":"چه کسی آدرس را کنترول می‌کند؟","Gefragt ist die handelnde Gruppe bei der Adresskontrolle.":"گروه انجام‌دهنده در کنترول آدرس خواسته شده است.","Die Kollegin nennt ausdrücklich das Versandteam.":"همکار صریح تیم ارسال را نام می‌برد.","Einen Ablauf beschreiben":"توضیح دادن یک جریان کار","Schreibe vier Sätze zum Versand: Auftrag prüfen, Waren zusammenstellen, Paket wiegen und verschicken. Nutze mindestens zwei Passivsätze.":"چهار جمله دربارهٔ ارسال بنویس: بررسی سفارش، جمع کردن اجناس، وزن کردن و فرستادن بسته. دست کم دو جملهٔ Passiv به کار ببر.","Prüfe vor jedem „werden“, ob das Subjekt Singular oder Plural ist.":"پیش از هر „werden“ بررسی کن که فاعل مفرد است یا جمع.","Die vier Sätze beschreiben den Vorgang aus Sicht der bearbeiteten Dinge.":"این چهار جمله جریان را از نظر چیزهایی که روی آن‌ها کار می‌شود توضیح می‌دهند.","Bleibt die Reihenfolge vom Auftrag bis zum Versand erhalten?":"آیا ترتیب از سفارش تا فرستادن حفظ شده است؟","Enthält dein Text mindestens zwei Passivsätze?":"آیا متنت دست کم دو جملهٔ Passiv دارد؟","Passen „wird“ und „werden“ zur Zahl des Subjekts?":"آیا „wird“ و „werden“ با تعداد فاعل مناسب‌اند؟","Verwendest du die Partizipien „zusammengestellt“ und „verschickt“ richtig?":"آیا Partizipهای „zusammengestellt“ و „verschickt“ را درست به کار می‌بری؟","Das Vorgangspassiv im Präsens besteht aus werden und Partizip II.":"Passiv جریانی در زمان حال از werden و Partizip II ساخته می‌شود.","Eine Prozessbeschreibung ersetzt keine nötige Zuständigkeitsklärung.":"توضیح یک جریان کار، روشن ساختنِ لازمِ مسئولیت را جبران نمی‌کند.","Probleme frühzeitig und sachlich melden":"زود و واقع‌بینانه خبر دادن مشکلات","Du benennst eine Abweichung, ihre Auswirkung und einen möglichen nächsten Schritt.":"یک انحراف از پلان، اثر آن و یک قدم بعدی ممکن را نام می‌بری.","Folge im sodass-Satz falsch ordnen":"ترتیب غلط نتیجه در جملهٔ sodass","Falsch: „Die Teile fehlen, sodass wir können nicht packen.“ Richtig: „Die Teile fehlen, sodass wir nicht packen können.“":"غلط: „Die Teile fehlen, sodass wir können nicht packen.“ درست: „Die Teile fehlen, sodass wir nicht packen können.“","Nachfrage als Bestätigung behandeln":"یک پرسش را مثل تأیید دانستن","Falsch: „Die Teile kommen morgen“, weil eine Anfrage versandt wurde. Richtig: „Der Liefertermin ist angefragt, aber noch unbestätigt.“":"غلط: „Die Teile kommen morgen“، چون یک پرسش فرستاده شده است. درست: „Der Liefertermin ist angefragt, aber noch unbestätigt.“","Welche Information ist bereits sicher?":"کدام معلومات از قبل مطمئن است؟","Die Teile kommen morgen früh.":"پرزه‌ها فردا صبح می‌رسند.","Für den Auftrag fehlen vier Teile.":"برای سفارش چهار پرزه کم است.","Der Kunde hat den Auftrag abgesagt.":"مشتری سفارش را لغو کرده است.","Nur der Fehlbestand ist beobachtet; ein Liefertermin wird noch geklärt.":"فقط کمبود دیده شده است؛ وقت تحویل هنوز روشن می‌شود.","Welche Aussage formuliert eine Möglichkeit?":"کدام جمله یک امکان را بیان می‌کند؟","Wir könnten die vorhandenen Teile vorbereiten.":"می‌توانستیم پرزه‌های موجود را آماده کنیم.","Die vollständige Lieferung ist bestätigt.":"تحویل کامل تأیید شده است.","Morgen wird garantiert alles versandt.":"فردا حتماً همه چیز فرستاده می‌شود.","„Könnten“ stellt einen Vorschlag dar und behauptet keine abgeschlossene Entscheidung.":"„Könnten“ یک پیشنهاد است و ادعای یک تصمیمِ قطعی نمی‌کند.","Welcher sodass-Satz ist korrekt?":"کدام جملهٔ sodass درست است؟","Die Verbgruppe „packen können“ steht am Ende des Folgesatzes.":"گروه فعلی „packen können“ در آخر جملهٔ نتیجه می‌آید.","Kennzeichne in einer Problemmeldung, was sicher beobachtet und was erst eine mögliche Lösung ist.":"در یک گزارش مشکل نشانی کن که چه چیزی مطمئن دیده شده و چه چیزی فقط یک راه‌حل ممکن است.","Eine verzögerte Lieferung besprechen":"گفت‌وگو دربارهٔ یک تحویلِ دیرشده","Tarek: „Für den Auftrag fehlen noch vier Teile. Deshalb können wir ihn heute nicht vollständig packen.“ Chefin: „Ist der Liefertermin der Teile bestätigt?“ Tarek: „Noch nicht. Ich habe beim Lager nachgefragt.“ Chefin: „Was schlagen Sie vor?“ Tarek: „Wir könnten die vorhandenen Teile vorbereiten und den Versandtermin erst nach der Rückmeldung bestätigen.“ Er trennt den bekannten Fehlbestand von der noch unklaren Lieferzeit.":"Tarek: „Für den Auftrag fehlen noch vier Teile. Deshalb können wir ihn heute nicht vollständig packen.“ رئیس: „Ist der Liefertermin der Teile bestätigt?“ Tarek: „Noch nicht. Ich habe beim Lager nachgefragt.“ رئیس: „Was schlagen Sie vor?“ Tarek: „Wir könnten die vorhandenen Teile vorbereiten und den Versandtermin erst nach der Rückmeldung bestätigen.“ او کمبودِ معلوم را از وقت تحویلِ هنوز ناروشن جدا می‌کند.","Folge und Alternative verbinden":"وصل کردن نتیجه و بدیل","„Die Teile fehlen, sodass wir den Auftrag nicht fertig packen können“ beschreibt eine Folge im Nebensatz. Das konjugierte Verb „können“ steht nach „packen“ am Ende. Mit „deshalb“ wäre ein neuer Hauptsatz möglich: „Deshalb können wir nicht fertig packen.“ Eine Alternative klingt mit „Wir könnten …“ vorsichtig. „Wir werden morgen liefern“ behauptet dagegen einen Plan, der ohne bestätigte Teile möglicherweise nicht einzuhalten ist.":"„Die Teile fehlen, sodass wir den Auftrag nicht fertig packen können“ یک نتیجه را در جملهٔ فرعی توضیح می‌دهد. فعل صرف‌شدهٔ „können“ بعد از „packen“ در آخر است. با „deshalb“ یک جملهٔ اصلی تازه ممکن می‌بود: „Deshalb können wir nicht fertig packen.“ یک بدیل با „Wir könnten …“ محتاطانه به نظر می‌رسد. „Wir werden morgen liefern“ برعکس ادعای پلانی را می‌کند که بدون پرزه‌های تأییدشده شاید عملی نشود.","Abweichungen genau bezeichnen":"دقیق نام بردن انحراف‌ها","Nützlich sind der Fehlbestand – die Fehlbestände, die Verzögerung – die Verzögerungen und die Alternative – die Alternativen. Eine Abweichung ist der Unterschied zwischen Planung und tatsächlichem Stand. „Vier Teile fehlen“ ist prüfbarer als „Es fehlt viel“. „Noch nicht bestätigt“ darf nicht als Absage verstanden werden. Beschreibe auch die betroffene Aufgabe, damit die Empfängerin die Bedeutung des Fehlbestands einschätzen kann.":"این کلمه‌ها مفیدند: der Fehlbestand – die Fehlbestände (کمبود)، die Verzögerung – die Verzögerungen (تأخیر) و die Alternative – die Alternativen (بدیل). انحراف فرق بین پلان و وضعیت واقعی است. „Vier Teile fehlen“ قابل بررسی‌تر از „Es fehlt viel“ (خیلی چیزها کم است) است. „Noch nicht bestätigt“ (هنوز تأیید نشده) نباید رد فهمیده شود. کارِ متأثر را هم توضیح بده تا گیرنده اهمیت کمبود را ارزیابی کند.","Mit einer konkreten Bitte abschließen":"ختم کردن با یک خواهش مشخص","Melde das Problem, sobald es den Ablauf beeinflusst, und nenne den bisher unternommenen Schritt. Eine Nachfrage beim Lager ist eine Handlung, aber noch keine Lösung. Bitte beispielsweise um Entscheidung, ob die vorhandenen Teile vorbereitet werden sollen. Halte eine Antwort fest, ohne eine technische oder organisatorische Ursache zu erfinden. So kann das Team weiterarbeiten und erkennt zugleich, was bis zur Rückmeldung offenbleibt.":"مشکل را به محض اینکه بر جریان کار اثر کرد خبر بده و قدمی را که تا حالا برداشته‌ای بگو. یک پرسش از گدام یک کار است، اما هنوز راه‌حل نیست. مثلاً تصمیم بخواه که آیا پرزه‌های موجود آماده شوند. یک جواب را یادداشت کن، بدون اینکه یک علت تخنیکی یا سازمانی بسازی. این طور تیم می‌تواند کار را ادامه بدهد و هم‌زمان می‌بیند که تا رسیدن جواب چه چیزی باز می‌ماند.","Eine Folge beschreiben":"توضیح دادن یک نتیجه","Ergänze „sodass“ und „können“.":"„sodass“ و „können“ را تکمیل کن.","Der Folgesatz endet mit dem gebeugten Modalverb.":"جملهٔ نتیجه با فعل کمکیِ صرف‌شده ختم می‌شود.","„Sodass“ führt die Folge ein; „können“ schließt deren Verbgruppe ab.":"„Sodass“ (طوری که) نتیجه را می‌آورد؛ „können“ گروه فعلی آن را ختم می‌کند.","Fakten und Vorschläge unterscheiden":"فرق واقعیت‌ها و پیشنهادها","Ordne die Aussage der Kategorie zu.":"هر جمله را به دستهٔ آن وصل کن.","Eine versandte Frage ist eine Handlung, keine Lieferzusage.":"یک سؤالِ فرستاده‌شده یک کار است، نه قول تحویل.","Die Kategorien trennen Befund, bisherige Reaktion und Vorschlag.":"این دسته‌ها یافته، واکنشِ تا حالا و پیشنهاد را از هم جدا می‌کنند.","Vier Teile fehlen.":"چهار پرزه کم است.","Der Liefertermin ist angefragt.":"وقت تحویل پرسیده شده است.","Wir könnten vorpacken.":"می‌توانستیم از پیش بسته‌بندی کنیم.","Den Fehlbestand hören":"شنیدن کمبود","Wie viele Teile fehlen? Schreibe eine Ziffer.":"چند پرزه کم است؟ یک عدد بنویس.","Gesucht ist der fehlende, nicht der vorhandene Bestand.":"موجودیِ کم خواسته شده، نه موجودیِ موجود.","Vier Teile werden noch benötigt.":"چهار پرزه هنوز لازم است.","Eine Abweichung melden":"خبر دادن یک انحراف","Schreibe eine kurze Meldung: vier fehlende Teile, Auftrag nicht vollständig packbar, Lager angefragt, Vorbereitung als Vorschlag.":"یک گزارش کوتاه بنویس: چهار پرزهٔ کم، سفارش کاملاً بسته‌بندی شده نمی‌تواند، از گدام پرسیده شده، آماده کردن به عنوان پیشنهاد.","Stelle die Rückfrage erst, nachdem du Stand und bisherige Nachfrage beschrieben hast.":"سؤال را فقط بعد از توضیح وضعیت و پرسشِ تا حالا مطرح کن.","Die Meldung ermöglicht eine Entscheidung, ohne einen unbekannten Termin vorzugeben.":"این گزارش تصمیم گرفتن را ممکن می‌سازد، بدون اینکه یک وقت ناشناخته را تعیین کند.","Ist die fehlende Menge mit vier Teilen angegeben?":"آیا مقدار کم با چهار پرزه گفته شده است؟","Beschreibst du die Folge für das Packen des Auftrags?":"آیا نتیجه را برای بسته‌بندی سفارش توضیح می‌دهی؟","Bleibt der Liefertermin ausdrücklich unbestätigt?":"آیا وقت تحویل صریح تأییدنشده می‌ماند؟","Kennzeichnest du das Vorbereiten als Vorschlag mit Entscheidungsfrage?":"آیا آماده کردن را به عنوان پیشنهاد با سؤال تصمیم نشانی می‌کنی؟","Eine Nachfrage ist noch keine Bestätigung eines Termins.":"یک پرسش هنوز تأیید یک وقت نیست.","Eine Problemmeldung nennt die konkrete Auswirkung auf den Auftrag.":"یک گزارش مشکل اثر مشخص بر سفارش را می‌گوید.","Fachwörter aus dem Zusammenhang erschließen":"فهمیدن اصطلاحات تخصصی از زمینه","Du entwickelst eine überprüfbare Vermutung zu einem Fachwort und sicherst die Bedeutung durch Rückfragen.":"دربارهٔ یک اصطلاح تخصصی یک حدسِ قابل بررسی می‌سازی و معنا را با سؤال کردن مطمئن می‌کنی.","Eine Vermutung als sichere Bedeutung ausgeben":"یک حدس را مثل معنای مطمئن گفتن","Falsch: „Charge bedeutet immer Preis“, ohne den Zusammenhang zu prüfen. Richtig: „In diesem Ablauf ist die Produktionskennzeichnung gemeint; ich lasse mir das bestätigen.“":"غلط: „Charge bedeutet immer Preis“، بدون بررسی زمینه. درست: „In diesem Ablauf ist die Produktionskennzeichnung gemeint; ich lasse mir das bestätigen.“","Artikel beim Fachwort weglassen":"جا انداختن حرف تعریف در اصطلاح تخصصی","Falsch: Nur „Begriff“ ohne Beispielsatz und Artikel notieren. Richtig: „der Begriff – die Begriffe; einen Begriff erklären“ festhalten.":"غلط: فقط „Begriff“ را بدون جملهٔ مثال و حرف تعریف یادداشت کردن. درست: „der Begriff – die Begriffe; einen Begriff erklären“ را یادداشت کردن.","Was macht Ina vor dem Eintragen richtig?":"Ina پیش از نوشتن چه کاری را درست انجام می‌دهد؟","Sie lässt ihre Vermutung zur Bedeutung bestätigen.":"حدسش دربارهٔ معنا را تأیید می‌گیرد.","Sie trägt eine zufällige Nummer ein.":"یک شمارهٔ تصادفی می‌نویسد.","Sie überspringt das unbekannte Feld.":"از خانهٔ ناشناخته می‌گذرد.","Ina überprüft ihre Deutung durch eine konkrete Rückfrage und erhält eine Bestätigung.":"Ina تعبیر خود را با یک سؤال مشخص بررسی می‌کند و تأیید می‌گیرد.","Welche Wortkarte ist am hilfreichsten?":"کدام کارت لغت از همه مفیدتر است؟","Charge: irgendetwas auf dem Blatt.":"Charge: یک چیزی روی ورق.","Charge, ohne Artikel und ohne Verwendung.":"Charge، بدون حرف تعریف و بدون کاربرد.","die Charge – die Chargen; im Beispiel gemeinsam gekennzeichnete Produktionsmenge.":"die Charge – die Chargen؛ در مثال: مقدار تولیدی که با هم نشانی شده است.","Artikel, Plural und Erklärung im Kontext unterstützen einen präzisen Gebrauch.":"حرف تعریف، جمع و توضیح در زمینه، کاربرد دقیق را کمک می‌کنند.","Welche Frage prüft eine Vermutung?":"کدام سؤال یک حدس را بررسی می‌کند؟","Warum gibt es überhaupt Wörter?":"اصلاً چرا کلمه‌ها وجود دارند؟","Ist damit die Nummer auf der Verpackung gemeint?":"آیا منظور شمارهٔ روی بسته‌بندی است؟","Kann ich jedes beliebige Feld ausfüllen?":"آیا می‌توانم هر خانه‌ای را پر کنم؟","Die Frage benennt genau die vermutete Bedeutung und lässt sie bestätigen oder korrigieren.":"این سؤال دقیقاً معنای حدس‌زده را نام می‌برد و اجازه می‌دهد تأیید یا اصلاح شود.","Notiere ein neues Fachwort zusammen mit einem Beispielsatz und einer bestätigten Erklärung aus deinem Arbeitsbereich.":"یک اصطلاح تخصصی تازه را همراه با یک جملهٔ مثال و یک توضیحِ تأییدشده از رشتهٔ کاری‌ات یادداشت کن.","Ein unbekanntes Wort im Betrieb klären":"روشن کردن یک کلمهٔ ناشناخته در شرکت","Anleiter: „Bitte dokumentieren Sie die Charge auf dem Blatt.“ Ina: „Meinen Sie mit Charge die Kennzeichnung dieser gemeinsam hergestellten Produkte?“ Anleiter: „Ja, hier ist die Chargennummer auf der Verpackung.“ Ina: „Dann übertrage ich diese Nummer in das Feld Charge?“ Anleiter: „Genau.“ Ina hat aus dem Zusammenhang eine Vermutung gebildet und sie vor dem Eintragen bestätigen lassen. Ein ähnlich klingendes Wort wäre kein sicherer Ersatz.":"رهنما: „Bitte dokumentieren Sie die Charge auf dem Blatt.“ Ina: „Meinen Sie mit Charge die Kennzeichnung dieser gemeinsam hergestellten Produkte?“ رهنما: „Ja, hier ist die Chargennummer auf der Verpackung.“ Ina: „Dann übertrage ich diese Nummer in das Feld Charge?“ رهنما: „Genau.“ Ina از زمینه یک حدس ساخت و پیش از نوشتن آن را تأیید گرفت. یک کلمهٔ هم‌آوا جانشین مطمئنی نمی‌بود.","Bedeutungen mit damit ist gemeint erklären":"توضیح معناها با damit ist gemeint","„Mit Charge ist hier eine Produktionsmenge mit gemeinsamer Kennzeichnung gemeint“ erklärt die betriebliche Verwendung im Beispiel. „Bedeutet das, dass …?“ leitet eine Verständnisfrage ein. Im folgenden dass-Satz steht das gebeugte Verb hinten. Ein Begriff kann je nach Fachgebiet anders verwendet werden. Die bestätigte Erklärung gilt deshalb zunächst für diesen konkreten Ablauf und wird nicht ungeprüft auf jedes andere Gebiet übertragen.":"„Mit Charge ist hier eine Produktionsmenge mit gemeinsamer Kennzeichnung gemeint“ کاربرد کاری این کلمه را در مثال توضیح می‌دهد. „Bedeutet das, dass …?“ (آیا یعنی که …؟) یک سؤال فهم را شروع می‌کند. در جملهٔ dass بعدی فعل صرف‌شده در آخر است. یک اصطلاح می‌تواند در رشته‌های مختلف به شکل دیگر به کار برود. پس توضیحِ تأییدشده اول برای همین جریان مشخص معتبر است و بدون بررسی به هر رشتهٔ دیگر برده نمی‌شود.","Eine persönliche Wortkartei anlegen":"ساختن یک مجموعهٔ شخصی کارت‌های لغت","Lerne der Begriff – die Begriffe, die Kennzeichnung – die Kennzeichnungen und das Beispiel – die Beispiele. Zu einem Nomen gehören Artikel und, wenn gebräuchlich, Plural. Notiere außerdem eine typische Verbindung: „eine Charge dokumentieren“. Ein Bild oder eine Skizze kann helfen, ersetzt aber keine bestätigte Bedeutung. Bewahre vertrauliche Produktdaten oder interne Unterlagen nicht ungefragt in einer privaten Lernkartei auf.":"یاد بگیر: der Begriff – die Begriffe (اصطلاح)، die Kennzeichnung – die Kennzeichnungen (نشانه‌گذاری) و das Beispiel – die Beispiele (مثال). با یک اسم، حرف تعریف و اگر معمول باشد جمع آن هم می‌آید. همچنین یک ترکیب معمول را یادداشت کن: „eine Charge dokumentieren“. یک عکس یا رسم کمک می‌کند، اما جانشین یک معنای تأییدشده نیست. معلومات محرم محصولات یا اسناد داخلی را بدون اجازه در کارت‌های لغت شخصی نگه ندار.","Vermutungen gezielt überprüfen":"هدفمند بررسی کردن حدس‌ها","Zerlege lange Wörter in erkennbare Bestandteile, lies die benachbarten Sätze und prüfe den Arbeitszweck. Diese Hinweise liefern eine Hypothese, keine Gewissheit. Frage dann „Ist damit die Nummer auf der Verpackung gemeint?“. Wenn eine falsche Deutung die Arbeit beeinflussen könnte, beginne den Schritt erst nach der Klärung. Erkläre das Wort anschließend in eigenen Worten und bitte die anleitende Person um eine kurze Bestätigung.":"کلمه‌های طولانی را به قسمت‌های قابل شناخت تقسیم کن، جمله‌های همسایه را بخوان و هدف کار را بررسی کن. این نشانه‌ها یک فرضیه می‌دهند، نه اطمینان. بعد بپرس „Ist damit die Nummer auf der Verpackung gemeint?“. اگر یک تعبیر غلط بر کار اثر کرده بتواند، قدم را فقط بعد از روشن شدن شروع کن. بعد کلمه را به کلمات خودت توضیح بده و از رهنما یک تأیید کوتاه بخواه.","Die Bedeutung erfragen":"پرسیدن معنا","Ergänze „dass“ und „gemeint“.":"„dass“ و „gemeint“ را تکمیل کن.","Ein Wort eröffnet den Inhaltssatz, das andere ergänzt „ist“.":"یک کلمه جملهٔ محتوایی را باز می‌کند، کلمهٔ دیگر „ist“ را تکمیل می‌کند.","Die erste Frage prüft eine Handlung, die zweite die Bedeutung des Ausdrucks.":"سؤال اول یک کار را بررسی می‌کند، سؤال دوم معنای عبارت را.","Lernschritte verbinden":"وصل کردن قدم‌های یادگیری","Ordne die Handlung ihrem Zweck zu.":"هر کار را به هدف آن وصل کن.","Denke vom ersten Verstehen bis zur späteren Anwendung.":"از اولین فهمیدن تا کاربرد بعدی فکر کن.","Die Schritte ergänzen sich beim Erlernen eines unbekannten Fachbegriffs.":"این قدم‌ها در یاد گرفتن یک اصطلاح تخصصی ناشناخته همدیگر را تکمیل می‌کنند.","Nachbarsätze lesen":"خواندن جمله‌های همسایه","Bedeutung rückfragen":"پرسیدن معنا","Artikel und Beispiel notieren":"یادداشت کردن حرف تعریف و مثال","Den Ort der Kennzeichnung verstehen":"فهمیدن جای نشانه‌گذاری","Wo steht die Chargennummer? Antworte mit einem Nomen ohne Artikel.":"شمارهٔ Charge کجا است؟ با یک اسم بدون حرف تعریف جواب بده.","Beachte die Korrektur nach „sondern“.":"به اصلاح بعد از „sondern“ (بلکه) دقت کن.","Die gesuchte Kennzeichnung befindet sich auf der Verpackung.":"نشانه‌گذاریِ خواسته‌شده روی بسته‌بندی است.","Ein Fachwort im Kontext erklären":"توضیح دادن یک اصطلاح تخصصی در زمینه","Schreibe drei Sätze: die betriebliche Bedeutung von Charge im Beispiel, eine passende Rückfrage und einen Eintrag für die Wortkartei.":"سه جمله بنویس: معنای کاری Charge در مثال، یک سؤال مناسب و یک نوشته برای کارت لغت.","Beschränke die Erklärung auf den gerade beschriebenen Arbeitsablauf.":"توضیح را به همین جریان کارِ توضیح‌داده‌شده محدود کن.","Das Muster zeigt Bedeutung, Absicherung und eine datensparsame Lernnotiz.":"این نمونه معنا، مطمئن ساختن و یک یادداشت یادگیری با معلومات کم را نشان می‌دهد.","Bezieht sich deine Erklärung ausdrücklich auf das Beispiel?":"آیا توضیحت صریح به مثال مربوط است؟","Enthält dein Text eine konkrete Verständnisfrage?":"آیا متنت یک سؤال فهمِ مشخص دارد؟","Notierst du Artikel und Plural des Fachworts?":"آیا حرف تعریف و جمع اصطلاح تخصصی را یادداشت می‌کنی؟","Verzichtest du auf echte vertrauliche Produktdaten?":"آیا از معلومات محرم واقعی محصولات دوری می‌کنی؟","Ein Fachwort wird im konkreten Arbeitszusammenhang überprüft.":"یک اصطلاح تخصصی در زمینهٔ مشخص کار بررسی می‌شود.","Eine gute Wortkarte verbindet Form, Bedeutung und typischen Gebrauch.":"یک کارت لغت خوب شکل، معنا و کاربرد معمول را وصل می‌کند.","Eine Übergabe verständlich dokumentieren":"قابل فهم نوشتن تحویل کار","Du erstellst eine knappe Übergabe mit erledigten Aufgaben, offenem Punkt und nächster Zuständigkeit.":"یک تحویل کوتاه با کارهای انجام‌شده، نکتهٔ باز و مسئولیت بعدی می‌سازی.","Gepackt mit versandt verwechseln":"اشتباه گرفتن gepackt با versandt","Falsch: „Auftrag 18 ist verschickt“, obwohl nur das Packen erledigt ist. Richtig: „Auftrag 18 ist gepackt; der Versand wartet auf die Adresse.“":"غلط: „Auftrag 18 ist verschickt“، در حالی که فقط بسته‌بندی انجام شده است. درست: „Auftrag 18 ist gepackt; der Versand wartet auf die Adresse.“","Vor der Voraussetzung versenden":"فرستادن پیش از شرط","Falsch: „Erst versenden, danach die Adresse bestätigen lassen.“ Richtig: „Erst nach der Adressbestätigung versenden.“":"غلط: „Erst versenden, danach die Adresse bestätigen lassen.“ درست: „Erst nach der Adressbestätigung versenden.“","Was ist bei Auftrag 18 bereits erledigt?":"در سفارش 18 چه چیزی از قبل انجام شده است؟","Der Versand.":"فرستادن.","Das Packen.":"بسته‌بندی.","Die Adressbestätigung.":"تأیید آدرس.","Lena nennt nur das Packen als abgeschlossen; Etikett und Versand fehlen noch.":"Lena فقط بسته‌بندی را تمام‌شده می‌گوید؛ برچسپ و فرستادن هنوز مانده است.","Welche Voraussetzung gilt für den Versand?":"برای فرستادن کدام شرط وجود دارد؟","Ben hat Feierabend.":"وقت کار Ben تمام شده است.","Frau Roth wurde lediglich angeschrieben.":"به خانم Roth فقط نامه نوشته شده است.","Die Adresse ist bestätigt.":"آدرس تأیید شده است.","Die bestätigte Adresse ist ausdrücklich als Voraussetzung vereinbart.":"آدرسِ تأییدشده صریح به عنوان شرط توافق شده است.","Welchen Schritt übernimmt Ben?":"Ben کدام قدم را به عهده می‌گیرد؟","Den Posteingang auf die Antwort prüfen.":"صندوق پیام‌ها را برای جواب بررسی کردن.","Eine beliebige Adresse eintragen.":"یک آدرس دلخواه نوشتن.","Den Auftrag sofort als versandt markieren.":"سفارش را فوراً فرستاده‌شده نشانی کردن.","Ben sagt zu, nach der ausstehenden Antwort im Posteingang zu sehen.":"Ben قول می‌دهد که بعد از جوابِ مانده، صندوق پیام‌ها را ببیند.","Prüfe die Übergabe aus Sicht der nächsten Schicht: Kann sie ohne Rückfrage erkennen, was noch fehlt?":"تحویل را از نظر نوبت کاری بعدی بررسی کن: آیا بدون سؤال می‌تواند بفهمد چه چیزی هنوز کم است؟","Die nächste Schicht informieren":"خبر کردن نوبت کاری بعدی","Lena: „Auftrag 18 ist gepackt, aber noch nicht versandt. Das Adressetikett fehlt.“ Ben: „Wer kümmert sich darum?“ Lena: „Ich habe Frau Roth um die Adresse gebeten. Ihre Antwort steht noch aus.“ Ben: „Dann prüfe ich nachher den Posteingang.“ Lena: „Gut. Bitte verschicke das Paket erst, wenn die Adresse bestätigt ist.“ Lena übergibt einen nachvollziehbaren Stand und Ben übernimmt einen konkreten nächsten Schritt.":"Lena: „Auftrag 18 ist gepackt, aber noch nicht versandt. Das Adressetikett fehlt.“ Ben: „Wer kümmert sich darum?“ Lena: „Ich habe Frau Roth um die Adresse gebeten. Ihre Antwort steht noch aus.“ Ben: „Dann prüfe ich nachher den Posteingang.“ Lena: „Gut. Bitte verschicke das Paket erst, wenn die Adresse bestätigt ist.“ Lena یک وضعیتِ قابل فهم را تحویل می‌دهد و Ben یک قدم بعدیِ مشخص را به عهده می‌گیرد.","Voraussetzungen mit erst wenn ausdrücken":"بیان شرط‌ها با erst wenn","„Verschicke das Paket erst, wenn die Adresse bestätigt ist“ bedeutet, dass die Bestätigung vorausgehen muss. „Wenn“ bildet den Nebensatz, „erst“ betont die notwendige zeitliche Grenze. „Bevor du das Paket verschickst, prüfst du die Adresse“ setzt ebenfalls eine Reihenfolge. Nach dem vorangestellten bevor-Satz beginnt der Hauptsatz mit dem Verb. Unterscheide „gepackt“ und „versandt“: Das eine bestätigt nicht automatisch das andere.":"„Verschicke das Paket erst, wenn die Adresse bestätigt ist“ یعنی تأیید باید پیش‌تر بیاید. „Wenn“ جملهٔ فرعی را می‌سازد، „erst“ (تازه، فقط وقتی) روی حد زمانیِ لازم تأکید می‌کند. „Bevor du das Paket verschickst, prüfst du die Adresse“ هم یک ترتیب می‌گذارد. بعد از جملهٔ bevor در اول، جملهٔ اصلی با فعل شروع می‌شود. „gepackt“ (بسته‌بندی‌شده) و „versandt“ (فرستاده‌شده) را از هم جدا کن: یکی خودبه‌خود دیگری را تأیید نمی‌کند.","Statusangaben präzise benennen":"دقیق نام بردن وضعیت‌ها","Zur Übergabe gehören die Schicht – die Schichten, das Etikett – die Etiketten und die Voraussetzung – die Voraussetzungen. „Steht noch aus“ bedeutet, dass die Antwort erwartet wird und noch fehlt. „Übernommen“ bezeichnet eine zugesagte Aufgabe, nicht unbedingt deren Erledigung. Halte deshalb den aktuellen Stand mit Zeitbezug fest. Eine Nummer ist nur dann nützlich, wenn sie den Auftrag eindeutig identifiziert und im Betrieb verwendet werden darf.":"به تحویل این کلمه‌ها تعلق دارند: die Schicht – die Schichten (نوبت کاری)، das Etikett – die Etiketten (برچسپ) و die Voraussetzung – die Voraussetzungen (شرط). „Steht noch aus“ یعنی جواب انتظار می‌رود و هنوز نیامده است. „Übernommen“ (به عهده گرفته‌شده) یک وظیفهٔ قول‌داده‌شده را نشان می‌دهد، نه لزوماً انجام آن را. پس وضعیت فعلی را با ذکر زمان یادداشت کن. یک شماره فقط وقتی مفید است که سفارش را روشن مشخص کند و استفادهٔ آن در شرکت اجازه داشته باشد.","Abschluss ohne falsche Vollständigkeit":"ختم کردن بدون کامل نشان دادنِ غلط","Eine gute Übergabe nennt den gepackten Auftrag, das fehlende Etikett, die Anfrage bei Frau Roth und Bens Kontrolle des Posteingangs. Der Versand bleibt an die bestätigte Adresse gebunden. Lies die Notiz noch einmal und streiche ein vorschnelles „alles erledigt“. Bitte Ben, den nächsten Schritt kurz zu wiederholen. Später dokumentiert er die tatsächliche Erledigung getrennt von dieser Übergabe, damit ein geplanter Versand nicht als bereits erfolgt erscheint.":"یک تحویل خوب سفارشِ بسته‌بندی‌شده، برچسپِ کم، پرسش از خانم Roth و بررسی صندوق پیام‌ها توسط Ben را می‌گوید. فرستادن وابسته به آدرسِ تأییدشده می‌ماند. یادداشت را یک بار دیگر بخوان و یک „alles erledigt“ (همه انجام شد) شتاب‌زده را خط بزن. از Ben بخواه قدم بعدی را کوتاه تکرار کند. بعداً او انجام واقعی را جدا از این تحویل یادداشت می‌کند تا یک فرستادنِ پلان‌شده انجام‌شده به نظر نرسد.","Eine Voraussetzung formulieren":"نوشتن یک شرط","Ergänze „wenn“ und „prüfst“.":"„wenn“ و „prüfst“ را تکمیل کن.","Nach „erst“ folgt die Bedingung; nach dem bevor-Satz beginnt der Hauptsatz mit dem Verb.":"بعد از „erst“ شرط می‌آید؛ بعد از جملهٔ bevor جملهٔ اصلی با فعل شروع می‌شود.","Beide Formulierungen setzen die Prüfung vor den Versand.":"هر دو عبارت بررسی را پیش از فرستادن می‌گذارند.","Übergabestatus ordnen":"مرتب کردن وضعیت‌های تحویل","Verbinde die Angabe mit ihrem Stand.":"هر معلومات را به وضعیت آن وصل کن.","Die zugesagte Kontrolle ist noch keine eingegangene Antwort.":"بررسیِ قول‌داده‌شده هنوز جوابِ رسیده نیست.","Die Zuordnung hält drei unterschiedliche Statusangaben auseinander.":"این وصل کردن سه وضعیت مختلف را از هم جدا نگه می‌دارد.","Auftrag gepackt":"سفارش بسته‌بندی شده","Antwort von Frau Roth":"جواب خانم Roth","Posteingang prüfen":"صندوق پیام‌ها را بررسی کردن","Den Auftrag identifizieren":"شناختن سفارش","Welche Auftragsnummer wird übergeben? Schreibe nur die Zahl.":"کدام شمارهٔ سفارش تحویل داده می‌شود؟ فقط عدد را بنویس.","Nicht jeder erwähnte Auftrag ist Gegenstand der Übergabe.":"هر سفارشی که ذکر شد، موضوع تحویل نیست.","Die offene Adresse betrifft Auftrag 18.":"آدرسِ باز مربوط به سفارش 18 است.","Eine Übergabenotiz verfassen":"نوشتن یک یادداشت تحویل","Schreibe vier Sätze: Auftrag 18 gepackt, Etikett fehlt, Frau Roth angefragt, Ben prüft Antwort und versendet erst nach Bestätigung.":"چهار جمله بنویس: سفارش 18 بسته‌بندی شده، برچسپ کم است، از خانم Roth پرسیده شده، Ben جواب را بررسی می‌کند و فقط بعد از تأیید می‌فرستد.","Schreibe nur den bestätigten Stand und markiere noch ausstehende Antworten.":"فقط وضعیتِ تأییدشده را بنویس و جواب‌های هنوز مانده را نشانی کن.","Die Übergabe macht den nächsten Schritt und seine Voraussetzung nachvollziehbar.":"این تحویل قدم بعدی و شرط آن را قابل فهم می‌سازد.","Unterscheidest du gepackt und versandt eindeutig?":"آیا gepackt و versandt را روشن از هم جدا می‌کنی؟","Nennst du das fehlende Adressetikett?":"آیا برچسپ آدرسِ کم را می‌گویی؟","Bleibt Frau Roths Antwort als ausstehend gekennzeichnet?":"آیا جواب خانم Roth مانده نشانی شده است؟","Enthält Bens Aufgabe die notwendige Adressbestätigung vor dem Versand?":"آیا وظیفهٔ Ben تأیید لازم آدرس پیش از فرستادن را دارد؟","Die Übergabe trennt Erledigung, offenen Punkt und übernommene Folgeaufgabe.":"این تحویل کار انجام‌شده، نکتهٔ باز و وظیفهٔ بعدیِ به عهده گرفته‌شده را از هم جدا می‌کند.","„Erst wenn“ macht eine notwendige Voraussetzung deutlich.":"„Erst wenn“ یک شرط لازم را روشن می‌سازد."};})(typeof window!=="undefined"?window:globalThis);
